parameters.jsCode:
// 1. Extract original Airtable fields (Look back at the Trigger node)
// IMPORTANT: Ensure 'Airtable Trigger' matches your node's exact name
const triggerData = $('Batch Processing Loop').item.json; 
const fields = triggerData.fields;

const price = fields['Total Bid Price'];
const leadTime = fields['Lead Time (Days)'];
const supplier = fields['Supplier Name'];
const recordId = triggerData.id;

// 2. Extract AI Scores (From the current OpenAI node output)
// Based on your output, the AI nested the data inside an "output" object
const aiOutput = $json; 
const esgScore = aiOutput.ESG_Score;
const riskScore = aiOutput.Risk_Score;

// 3. Set the Strategic Priority 
const currentPriority = $('Fetch Priority').first().json.fields['Active Value'];

// 4. Define the Dynamic Weights Matrix
const weights = {
  "Balanced":        { price: 0.3, leadTime: 0.3, esg: 0.2, risk: 0.2 },
  "ESG_Focus":       { price: 0.2, leadTime: 0.2, esg: 0.5, risk: 0.1 },
  "Speed_to_Market": { price: 0.2, leadTime: 0.5, esg: 0.1, risk: 0.2 },
  "Cost_Reduction":  { price: 0.6, leadTime: 0.1, esg: 0.1, risk: 0.2 }
};

const activeWeights = weights[currentPriority];

// 5. Normalize Price and Lead Time to a 1-10 scale
const priceScore = Math.max(1, 10 - (price / 20000)); 
const leadTimeScore = Math.max(1, 10 - (leadTime / 9));

// 6. Calculate Final Weighted Score (out of 100)
const totalScore = (
  (priceScore * activeWeights.price) +
  (leadTimeScore * activeWeights.leadTime) +
  (esgScore * activeWeights.esg) +
  (riskScore * activeWeights.risk)
) * 10; 

// 7. Output the fully enriched data object
return {
  recordId: recordId,
  supplierName: supplier,
  priorityApplied: currentPriority,
  finalScore: Math.round(totalScore),
  breakdown: {
    priceScore: parseFloat(priceScore.toFixed(1)),
    leadTimeScore: parseFloat(leadTimeScore.toFixed(1)),
    esgScore: esgScore,
    riskScore: riskScore
  },
  aiReasoning: {
    esg: aiOutput.ESG_Reasoning,
    risk: aiOutput.Risk_Reasoning
  }
};

// Grab the sorted batch of suppliers
const items = $input.all();

// Loop through them and assign a rank based on their sorted position
items.forEach((item, index) => {
    // Index 0 becomes Rank 1, Index 1 becomes Rank 2, etc.
    item.json.batchRank = index + 1; 
});

return items;
